    private readonly BuildingNode _buildingNode=new();private BuildingPreview _buildingPreview=null!;private PanelContainer _buildingPanel=null!;
    private readonly List<SpinBox> _buildingFields=new();private SpinBox _buildingHeight=null!,_buildingVariation=null!,_buildingPassage=null!,_buildingFoundation=null!,_buildingRoof=null!,_buildingSeed=null!;
    private CheckButton _buildingParty=null!,_buildingInstitutions=null!;private OptionButton _buildingLayer=null!;private Button _buildingRun=null!,_buildingCancel=null!;private Label _buildingState=null!,_buildingSummary=null!;
    private CancellationTokenSource? _buildingCancellation;private int _selectedBuilding=-1;
    private BuildingOptions BuildingSettings()=>new((float)_buildingHeight.Value,(float)_buildingVariation.Value,(float)_buildingPassage.Value,(float)_buildingFoundation.Value,(float)_buildingRoof.Value,(int)_buildingSeed.Value,_buildingParty.ButtonPressed,_buildingInstitutions.ButtonPressed);
    public BuildingSet? CurrentBuildings=>_buildingNode.IsCurrent(CurrentParcels,_parcelNode.ResultRevision,BuildingSettings())?_buildingNode.LastResult:null;
    private void BuildBuildingInterface(Control root){
        _buildingPreview=new BuildingPreview{Name="BuildingPreview"};AddChild(_buildingPreview);var selector=(OptionButton)root.GetNode("PcgNodeSelector");selector.AddItem("05 建筑体量");
        _buildingPanel=new PanelContainer{Name="BuildingPanel",Visible=false};root.AddChild(_buildingPanel);_buildingPanel.SetAnchorsAndOffsetsPreset(Control.LayoutPreset.RightWide);_buildingPanel.OffsetLeft=-344;_buildingPanel.OffsetRight=-24;_buildingPanel.OffsetTop=66;_buildingPanel.OffsetBottom=-129;_buildingPanel.AddThemeStyleboxOverride("panel",Box(new Color(.075f,.12f,.1f,.96f),12,18));selector.ItemSelected+=i=>_buildingPanel.Visible=i==BuildingStage;
        var scroll=new ScrollContainer{HorizontalScrollMode=ScrollContainer.ScrollMode.Disabled};_buildingPanel.AddChild(scroll);var col=new VBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};col.AddThemeConstantOverride("separation",6);scroll.AddChild(col);col.AddChild(Text("建筑体量",24,Ink));col.AddChild(Text("输入：有效地块与同版环境",12,Muted));
        var actions=new HBoxContainer();col.AddChild(actions);_buildingRun=Button("独立生成建筑");_buildingCancel=Button("取消");_buildingCancel.Disabled=true;actions.AddChild(_buildingRun);actions.AddChild(_buildingCancel);_buildingRun.Pressed+=async()=>await RunBuildingsAsync();_buildingCancel.Pressed+=()=>_buildingCancellation?.Cancel();
        _buildingState=Text("未运行",12,Accent);_buildingState.AutowrapMode=TextServer.AutowrapMode.WordSmart;col.AddChild(_buildingState);_buildingSummary=Text("生成后显示城内外数量与问题",12,Muted);_buildingSummary.AutowrapMode=TextServer.AutowrapMode.WordSmart;col.AddChild(_buildingSummary);
        _buildingLayer=new OptionButton();foreach(string title in new[]{"隐藏建筑","体量总览","功能与来源","占地与通行","地形与问题"})_buildingLayer.AddItem(title);col.AddChild(_buildingLayer);_buildingLayer.ItemSelected+=_=>ShowBuildings();
        SpinBox Field(string title,double value,double min,double max,double step){var row=new HBoxContainer();col.AddChild(row);var label=Text(title,12,Muted);label.CustomMinimumSize=new(125,0);row.AddChild(label);var input=new SpinBox{MinValue=min,MaxValue=max,Step=step,Value=value,SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};row.AddChild(input);_buildingFields.Add(input);input.ValueChanged+=_=>InvalidateBuildings();return input;}
        _buildingHeight=Field("高度倍率",1,.4,2,.05);_buildingVariation=Field("局部变化",.2,0,.5,.05);_buildingPassage=Field("通院净宽 / m",1.2,.8,3,.1);_buildingFoundation=Field("基础高差 / m",1.5,.2,4,.1);_buildingRoof=Field("屋顶坡度 / 度",42,20,60,1);_buildingSeed=Field("建筑种子",73129,0,int.MaxValue,1);
        _buildingParty=new CheckButton{Text="允许合法共墙",ButtonPressed=true};col.AddChild(_buildingParty);_buildingParty.Toggled+=_=>InvalidateBuildings();_buildingInstitutions=new CheckButton{Text="生成公共院区体量",ButtonPressed=true};col.AddChild(_buildingInstitutions);_buildingInstitutions.Toggled+=_=>InvalidateBuildings();
        var views=new HBoxContainer();col.AddChild(views);var whole=Button("全城斜视");views.AddChild(whole);whole.Pressed+=()=>FocusBuildings("town");var top=Button("全城俯视");views.AddChild(top);top.Pressed+=FocusSettlement;
        var close=new HBoxContainer();col.AddChild(close);foreach(var item in new[]{("街屋近景","core"),("城外近景","suburb"),("院区近景","institution")}){var b=Button(item.Item1);close.AddChild(b);b.Pressed+=()=>FocusBuildings(item.Item2);}
        col.AddChild(Text("点击体量查看来源、屋顶与地基",12,Muted));
    }
    private void InvalidateBuildings(){_buildingNode.Invalidate();InvalidatePlacement();if(_buildingState!=null)RefreshBuildings();}
    private void HideBuildings(){if(_buildingLayer==null)return;_buildingLayer.Select(0);_buildingPreview.Display(_buildingNode.LastResult,0);}
    private void SetBuildingBusy(bool busy){if(_buildingRun==null)return;foreach(var field in _buildingFields)field.Editable=!busy;_buildingParty.Disabled=busy;_buildingInstitutions.Disabled=busy;_buildingRun.Disabled=busy;_buildingCancel.Disabled=!busy;}
    private void RefreshBuildings(){if(_buildingState==null)return;_buildingState.Text=_buildingNode.State switch{SampleNodeState.Valid=>CurrentBuildings!=null?"有效":"已过期",SampleNodeState.Stale=>"已过期",SampleNodeState.Running=>"生成中…",SampleNodeState.Failed=>"失败："+_buildingNode.Error,SampleNodeState.Cancelled=>"已取消",_=>"未运行"};if(CurrentParcels==null)_buildingState.Text+=" · 请先生成有效地块";if(_buildingNode.LastResult!=null&&CurrentBuildings==null)_buildingState.Text+="\n当前显示旧结果";
        if(_buildingNode.LastResult is {} d)_buildingSummary.Text=$"主屋 {d.OrdinaryCount} · 院区体块 {d.Buildings.Count-d.OrdinaryCount}\n城内 {d.InsideCount} · 城外 {d.OutsideCount}\n共墙 {d.SharedWalls.Count} · 跳过/问题 {d.Issues.Count}\n建筑占地 {d.FootprintArea/10000:0.00} 公顷\n沿街面宽占用 {d.FacadeCoverage:P0} · 采样 {d.Environment.StepX:0.#} m";
    }
    private async Task RunBuildingsAsync(){if(_busy)return;var input=CurrentParcels;var env=SampledEnvironment;if(input==null||env==null){_buildingState.Text="请先生成有效环境、布局、道路和地块";return;}
        InvalidatePlacement();
        _busy=true;_buildingCancellation=new();SetSamplingBusy(true);SetLayoutBusy(true);SetRoadBusy(true);SetParcelBusy(true);SetBuildingBusy(true);_sampleCancel.Disabled=true;_layoutCancel.Disabled=true;_roadCancel.Disabled=true;_parcelCancel.Disabled=true;_selectedBuilding=-1;
        try{var result=await _buildingNode.RunAsync(env,input,_sampleNode.ResultRevision,_parcelNode.ResultRevision,BuildingSettings(),new(_buildingCancellation.Token,async p=>{_buildingState.Text=$"{p.Message} {p.Fraction:P0}";await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);}));if(_buildingLayer.Selected==0)_buildingLayer.Select(1);ShowBuildings();GD.Print($"BUILDINGS_READY ordinary={result.OrdinaryCount} institutions={result.Buildings.Count-result.OrdinaryCount} shared={result.SharedWalls.Count} revision={_buildingNode.ResultRevision}");}
        catch(OperationCanceledException){GD.Print("BUILDINGS_CANCELLED");}catch(Exception ex){GD.PrintErr("BUILDINGS_FAILED: "+ex.Message);}
        finally{_buildingCancellation.Dispose();_buildingCancellation=null;_busy=false;SetSamplingBusy(false);SetLayoutBusy(false);SetRoadBusy(false);SetParcelBusy(false);SetBuildingBusy(false);RefreshBuildings();}
    }
    private void ShowBuildings(){var d=_buildingNode.LastResult;if(_buildingLayer.Selected>0&&d!=null){HidePlacement();SetSampleLayer(EnvironmentPreviewLayer.Hidden);HideRoads();HideParcels();_layoutLayer.Select(0);_layoutPreview.Display(d.Parcels.Settlement,0,false);_roadPreview.Display(d.Parcels.Roads,1,respectDepth:true);_townPreview.Display(d.Parcels.Settlement,d.Parcels.Roads,false,true);_trees.SetPressedNoSignal(false);_map.ShowForest(false);_view.Select(0);_map.SetView(TerrainView.Landscape);_legend.Text=_buildingLayer.Selected switch{2=>"建筑功能 / 住宅 · 商住 · 作坊住宅 · 公共院区（点击查看来源）",3=>"建筑占地 / 金：主屋和屋檐 · 青：侧道或共享通院 · 紫：共墙",4=>"地形检查 / 绿→红：地基高差升高 · 红叉：跳过地块",_=>"建筑灰模 / 主屋、双坡屋顶、地基、通院预留与院区体量"};}_buildingPreview.Display(d,_buildingLayer.Selected,_selectedBuilding);}
    private void FocusBuildings(string kind){var d=_buildingNode.LastResult;if(d==null)return;if(kind=="town"){FocusSettlement();_camera.Pitch=1.05f;_camera.Yaw=-.2f;_camera.UpdateTransform();return;}
        var b=kind switch{"institution"=>d.Buildings.FirstOrDefault(x=>x.PrecinctId=="abbey"),"suburb"=>d.Buildings.Where(x=>x.ParcelId.HasValue&&!x.InsideCore).OrderBy(x=>x.Footprint.Center.DistanceSquaredTo(d.Parcels.Settlement.Core)).FirstOrDefault(),_=>d.Buildings.Where(x=>x.ParcelId.HasValue&&x.InsideCore).OrderBy(x=>x.Footprint.Center.DistanceSquaredTo(d.Parcels.Settlement.Core)).FirstOrDefault()};
        if(b==null){_buildingState.Text="当前结果没有该类建筑";return;}var p=b.Footprint.Center;_camera.Focus=new Vector3(p.X,b.BaseY+3,p.Y);_camera.Size=kind=="institution"?190:130;_camera.Pitch=.9f;_camera.Yaw=-.35f;_camera.UpdateTransform();
    }
    private int PickBuilding(Vector2 screen){var d=_buildingNode.LastResult;if(d==null)return -1;if(_buildingLayer.Selected==3){var ground=PickSettlementGround(screen);return ground.HasValue?d.Buildings.FirstOrDefault(b=>b.Footprint.Contains(ground.Value))?.Id??-1:-1;}
        var mesh=_buildingPreview.MeshData;if(mesh==null)return -1;var origin=_camera.ProjectRayOrigin(screen);var ray=_camera.ProjectRayNormal(screen);float nearest=float.PositiveInfinity;int found=-1;
        for(int i=0;i<mesh.Positions.Count;i+=3){var a=mesh.Positions[i];var e1=mesh.Positions[i+1]-a;var e2=mesh.Positions[i+2]-a;var p=ray.Cross(e2);float det=e1.Dot(p);if(Math.Abs(det)<1e-6)continue;var s=origin-a;float u=s.Dot(p)/det;if(u<0||u>1)continue;var q=s.Cross(e1);float v=ray.Dot(q)/det;if(v<0||u+v>1)continue;float distance=e2.Dot(q)/det;if(distance>0&&distance<nearest){nearest=distance;found=mesh.Owners[i];}}return found;
    }
    private bool UpdateBuildingProbe(Vector2 unused){if(_buildingLayer==null||_buildingLayer.Selected==0)return false;int id=PickBuilding(GetViewport().GetMousePosition());var b=_buildingNode.LastResult?.Buildings.FirstOrDefault(x=>x.Id==id);if(b==null){var issue=_buildingLayer.Selected==4?_buildingNode.LastResult?.Issues.OrderBy(i=>i.Position.DistanceSquaredTo(unused)).FirstOrDefault():null;_probe.Text=issue!=null&&issue.Position.DistanceTo(unused)<8?$"{issue.Source} · {issue.Reason}":"建筑 / 将光标移到建筑体量上";return true;}_probe.Text=$"{(CurrentBuildings==null?"旧建筑":"建筑")} B{b.Id} {b.Program} · 占地 {b.Footprint.Area:0} m² · 墙高 {b.WallHeight:0.0} m · 屋顶 {b.RoofHeight:0.0} m · 基础差 {b.BaseY-b.MinGround:0.00} m";return true;}
    private bool HandleBuildingClick(InputEvent ev){if(_busy||_buildingPanel==null||!_buildingPanel.Visible||_buildingLayer.Selected==0||ev is not InputEventMouseButton{Pressed:true,ButtonIndex:MouseButton.Left} mouse)return false;_selectedBuilding=PickBuilding(mouse.Position);var b=_buildingNode.LastResult?.Buildings.FirstOrDefault(x=>x.Id==_selectedBuilding);if(b!=null)_buildingState.Text=$"{(CurrentBuildings==null?"旧结果 · ":"")}B{b.Id} {b.Program}\n来源 {(b.ParcelId.HasValue?$"地块 P{b.ParcelId}":b.PrecinctId)}\n门口 {b.Door.X:0.#}, {b.Door.Y:0.#} · {(b.OpenHall?"通高大厅":$"{b.Floors} 层体量")}";else if(_buildingLayer.Selected==4&&PickSettlementGround(mouse.Position) is {} ground){var issue=_buildingNode.LastResult?.Issues.OrderBy(i=>i.Position.DistanceSquaredTo(ground)).FirstOrDefault();if(issue!=null&&issue.Position.DistanceTo(ground)<8)_buildingState.Text=$"{issue.Source}\n{issue.Reason}";}ShowBuildings();GetViewport().SetInputAsHandled();return true;}
